import React, { useState, useEffect } from 'react';
import axios from 'axios';
import './App.css';

function App() {
  const [tasks, setTasks] = useState([]);
  const [modalOpen, setModalOpen] = useState(false);
  const [newTask, setNewTask] = useState('');
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    axios.get('/tasks').then((res) => setTasks(res.data));
  }, []);

  const handleCreateTask = async () => {
    if (!newTask.trim()) return;
    setLoading(true);
    try {
      const res = await axios.post('/tasks', { title: newTask });
      setTasks([...tasks, res.data]);
      setNewTask('');
      setModalOpen(false);
    } catch (err) {
      alert('Failed to create task.');
    }
    setLoading(false);
  };

  return (
    <div className="app">
      <h1>📝 Kanban Todo List</h1>
      <button className="new-task-btn" onClick={() => setModalOpen(true)}>+ New Task</button>

      {modalOpen && (
        <div className="modal">
          <textarea
            placeholder="Enter task title"
            value={newTask}
            onChange={(e) => setNewTask(e.target.value)}
          />
          <div className="modal-buttons">
            <button onClick={handleCreateTask} disabled={loading}>
              {loading ? 'Creating...' : 'Create'}
            </button>
            <button onClick={() => setModalOpen(false)}>Cancel</button>
          </div>
        </div>
      )}

      <div className="kanban">
        {tasks.map((task) => (
          <div key={task.id} className="card">
            <h3>{task.title}</h3>
            <pre>{task.instructions}</pre>
            <small>{new Date(task.timestamp).toLocaleString()}</small>
          </div>
        ))}
      </div>
    </div>
  );
}

export default App;
